package local.aicenter.core;
public final class FactorialDesignTest {
 private static int checks;
 private static void near(double a,double b){checks++;if(Math.abs(a-b)>1e-9*Math.max(1,Math.abs(b)))throw new AssertionError(a+" != "+b);}
 private static void yes(boolean b){checks++;if(!b)throw new AssertionError("check "+checks);}
 private static void reject(Runnable r){checks++;try{r.run();throw new AssertionError("accepted invalid design");}catch(IllegalArgumentException expected){}}
 public static final String DATA="run,A,B,Y\n1,-1,-1,11.5\n2,-1,-1,13.5\n3,1,-1,12.5\n4,1,-1,14.5\n5,-1,1,2.5\n6,-1,1,4.5\n7,1,1,9.5\n8,1,1,11.5";
 private static FactorialDesign.Result run(String data){return FactorialDesign.analyze(2,2,data,"N·m",true);}
 public static void main(String[] args){FactorialDesign.Result r=run(DATA);near(r.mean,10);near(r.sse,8);near(r.mse,2);near(r.sst,130);yes(r.errorDf==4&&r.terms.size()==3);double[] ef={4,-6,3},ss={32,72,18},p={.016130089900092532,.0038825370469605146,.03994196807171877};for(int i=0;i<3;i++){near(r.terms.get(i).effect,ef[i]);near(r.terms.get(i).coefficient,ef[i]/2);near(r.terms.get(i).ss,ss[i]);near(r.terms.get(i).f,ss[i]/2);near(r.terms.get(i).p,p[i]);}yes(r.report().contains("响应单位：N·m"));near(run(DATA.substring(DATA.indexOf('\n')+1)).sst,130);String[] lines=DATA.split("\n");StringBuilder shuffled=new StringBuilder(lines[0]);for(int i=lines.length-1;i>0;i--)shuffled.append('\n').append(lines[i]);near(run(shuffled.toString()).terms.get(1).effect,-6);
 for(int k=2;k<=4;k++){String plan=FactorialDesign.plan(k,3,42);yes(plan.equals(FactorialDesign.plan(k,3,42)));yes(!plan.equals(FactorialDesign.plan(k,3,43)));String[] rows=plan.trim().split("\n");yes(rows.length==3*(1<<k)+1);StringBuilder measured=new StringBuilder(rows[0]);int[] counts=new int[1<<k];for(int i=1;i<rows.length;i++){String[] cells=rows[i].split(",",-1);int mask=0;double y=20;for(int j=0;j<k;j++){int sign=Integer.parseInt(cells[j+1]);yes(sign==-1||sign==1);if(sign==1)mask|=1<<j;y+=(j+1)*sign;}counts[mask]++;measured.append('\n').append(rows[i]).append(y+counts[mask]-2);}for(int c:counts)yes(c==3);FactorialDesign.Result multi=FactorialDesign.analyze(k,3,measured.toString(),"scalar",true);near(multi.mean,20);near(multi.sse,2*(1<<k));for(int j=0;j<k;j++)near(multi.terms.get((1<<j)-1).effect,2*(j+1));}
 reject(()->run(DATA.replace("8,1,1,11.5","8,-1,1,11.5")));reject(()->run(DATA.replace("8,1,1,11.5","7,1,1,11.5")));reject(()->run(DATA.replace("8,1,1,11.5","8,0,1,11.5")));reject(()->run(DATA.replace("11.5","NaN")));reject(()->run(DATA+"\n"+lines[1]));reject(()->run(DATA.replace("\n2,-1,-1,13.5","")));reject(()->run(FactorialDesign.plan(2,2,4)));reject(()->FactorialDesign.plan(5,2,0));reject(()->FactorialDesign.plan(2,1,0));reject(()->FactorialDesign.analyze(2,2,DATA,"",true));reject(()->FactorialDesign.analyze(2,2,DATA,"mm",false));
 String constant=DATA.replaceAll(",[0-9]+\\.[0-9]+(?=\\n|$)",",10");r=run(constant);near(r.mse,0);yes(Double.isNaN(r.terms.get(0).p));yes(r.report().contains("F/p未定义"));System.out.println("PASS factorial DOE: "+checks+" assertions (host synthetic; limited full-factorial model)");}
}
